-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8613, 21, 'Sozialleistungen automatisch bzw. antragslos auszahlen, Datenaustausch zwischen Behörden (Bund)', 'Automatische Gewährung erhöht die Inanspruchnahme laut Forschung deutlich, Verwaltungshürden senken sie. Dagegen: Datenaustausch und IT brauchen mehrere Jahre, bei bereits hoch genutzten Leistungen wie Kindergeld ist der Zugewinn klein.', 'belegt', 'https://www.nber.org/papers/w10488', 'bund', null, true, 'blind'),
  (8614, 21, 'Aktiv über Ansprüche informieren und beim Antrag helfen (Bund)', 'Experimente zeigen: Information erhöht die Inanspruchnahme, mit Antragshilfe noch stärker. Dagegen: Effekte bleiben begrenzt und erreichen die Bedürftigsten schlechter.', 'belegt', 'https://www.nber.org/papers/w24652', 'bund', null, true, 'blind'),
  (8615, 21, 'Regelsätze regelmäßig an die Preisentwicklung anpassen (Bund)', 'Sichert die Kaufkraft und verhindert, dass Regelsätze hinter der Inflation zurückbleiben. Dagegen: Eine Fortschreibung besteht bereits; die Lücke durch die Bemessung selbst bleibt unberührt.', 'offen', null, 'bund', null, true, 'blind'),
  (8616, 21, 'Steuerliche Entlastung für Alleinerziehende ausbauen oder als Abzug von der Steuerschuld gestalten (Bund)', 'Entlastet erwerbstätige Alleinerziehende, als Abzug von der Steuerschuld stärker bei kleinen Einkommen. Dagegen: Wer kaum Steuern zahlt, etwa im Grundsicherungsbezug, profitiert ohne Auszahlung kaum.', 'offen', null, 'bund', null, true, 'blind'),
  (8617, 21, 'Elterngeld-Mindestbetrag und Ersatzrate für geringe Einkommen anheben (Bund)', 'Erhöht das Einkommen von Familien mit kleinen Einkommen im ersten Lebensjahr. Dagegen: zeitlich begrenzt und bei Grundsicherungsbezug weitgehend angerechnet.', 'offen', null, 'bund', null, true, 'blind'),
  (8618, 21, 'Kindergeld an die Entwicklung des Kinderfreibetrags koppeln bzw. angleichen (Bund)', 'Höheres Kindergeld erreicht alle Familien. Dagegen: Es wird auf die Grundsicherung angerechnet und senkt Armutsrisiken laut Evaluationen daher nur wenig; teuer bei geringer Zielgenauigkeit.', 'gemischt', null, 'bund', null, true, 'blind'),
  (8619, 21, 'Unterhaltsvorschuss: Kindergeld nur teilweise anrechnen, Bezugsdauer ausweiten (Bund)', 'Erhöht die Leistung für Alleinerziehende ohne Unterhalt. Dagegen: Im Grundsicherungsbezug wird der Unterhaltsvorschuss angerechnet, der Zugewinn kommt nur Haushalten oberhalb davon zugute.', 'offen', null, 'bund', null, true, 'blind'),
  (8620, 21, 'Existenzminimum und Umgangsmehrbedarf von Kindern in Trennungsfamilien absichern (Bund)', 'Deckt Mehrkosten, wenn Kinder in zwei Haushalten leben, und schließt so eine Lücke für Trennungsfamilien. Dagegen: betrifft eine begrenzte Gruppe, Ausgestaltung offen.', 'offen', null, 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
